"""Public service pages written for viewers."""
from website.views import layout, esc


def help_url(config):
    return config['bot_url'] + '?start=help'


def about(config):
    content = f'''<div class="page-shell service-page"><section class="page-intro"><span class="eyebrow muted">ДЛЯ ТЕХ, КТО ЖДЁТ</span><h1>Хорошее кино<br>стоит ждать<span class="lime">.</span></h1><p>КиноЖдун помогает найти следующий любимый фильм и не пропустить продолжение любимого сериала.</p></section><div class="service-grid"><section class="service-card"><span class="eyebrow lime">ВЫБИРАЙТЕ</span><h2>Ваш следующий вечер.</h2><p>Ищите знакомые названия, смотрите трейлеры и открывайте новые проекты. В календаре — ближайшие премьеры и новые серии.</p><a class="text-link" href="/catalog">Выбрать кино ↗</a></section><section class="service-card"><span class="eyebrow lime">СОХРАНЯЙТЕ</span><h2>Всё, что хочется увидеть.</h2><p>Добавляйте фильмы и сериалы в личный список в Telegram. Делитесь списком с друзьями и отмечайте свою дату ожидания.</p><a class="text-link" href="{esc(config['bot_url'])}" target="_blank" rel="noopener">Мой список ↗</a></section><section class="service-card"><span class="eyebrow lime">НЕ ПРОПУСКАЙТЕ</span><h2>Премьеры без суеты.</h2><p>Бот следит за изменениями и напоминает о выходе. А в канале можно читать подборки премьер на день и неделю.</p><a class="text-link" href="{esc(config['channel_url'])}" target="_blank" rel="noopener">Читать канал ↗</a></section></div><div class="service-prose"><h2>Кино для вашего списка.</h2><p>Мы собираем популярные фильмы, ожидаемые новинки, любимые сериалы и аниме. Каталог регулярно пополняется. Не нашли нужный проект? Попробуйте поиск — в нём доступно больше названий.</p><p>КиноЖдун — сервис ожидания, а не онлайн-кинотеатр. Смотрите фильмы на доступной вам платформе; российская, международная и цифровая премьеры могут приходиться на разные даты.</p><h2>Нужна подсказка?</h2><p>В <a href="/help">разделе помощи</a> есть ответы на частые вопросы. Начать пользоваться сервисом можно бесплатно — достаточно Telegram.</p><section class="source-credit"><h2>Данные и изображения</h2><p>Данные и изображения предоставлены <a href="https://www.themoviedb.org" target="_blank" rel="noopener">The Movie Database</a>.</p><img class="tmdb-logo" src="https://www.themoviedb.org/assets/2/v4/logos/v2/blue_short-8e7b30f73a4020692ccca9c88bafe5dcb6f8a62a4c6bc55cd9ba82bb2cd95f6c.svg" alt="TMDB"><p lang="en">This product uses the TMDB API but is not endorsed or certified by TMDB.</p></section></div></div>'''
    return layout(config, 'О КиноЖдуне', 'Выбирайте фильмы и сериалы, сохраняйте список ожидания и получайте напоминания о премьерах в Telegram.', content, '/about')


FAQ = [
    ('Как добавить фильм или сериал в список?', 'Найдите проект на сайте и нажмите «+ Ждать». Откроется бот в Telegram с карточкой проекта. Подтвердите добавление — проект появится в вашем списке.'),
    ('Нужно ли регистрироваться на сайте?', 'Отдельная регистрация не нужна. Ваш личный список хранится в Telegram-боте и привязан к вашей учётной записи Telegram.'),
    ('Какие уведомления приходят?', 'Бот сообщает об изменении статуса и появлении даты выхода. О премьере он напоминает за три дня, а о новой серии — накануне. Напоминания о сериях приходят в дневное время по Москве.'),
    ('Можно ли смотреть фильмы здесь?', 'На сайте доступны описания, трейлеры и даты выхода. Полные фильмы и серии смотрите в кинотеатрах и на доступных вам платформах.'),
    ('Почему дата выхода может измениться?', 'Премьеры переносят, а даты в разных странах и на разных платформах отличаются. КиноЖдун обновляет расписание; перед просмотром уточните доступность на своей платформе.'),
    ('Нужного проекта нет в каталоге. Что делать?', 'Введите его название в поиске сверху страницы. Можно искать и по оригинальному названию. Если поиск не дал результата, попробуйте найти проект в боте.'),
    ('Как задать свою дату?', 'Откройте бота, выберите «Своя дата», затем проект из своего списка. Введите дату в формате ДД.ММ.ГГГГ. Если до неё осталось не меньше трёх дней, бот успеет отправить напоминание.'),
    ('Как поделиться списком?', 'В боте откройте «Мой Кинождун» и нажмите «Поделиться списком». Друг получит копию выбранных проектов. Ваши последующие изменения не меняют уже отправленную копию.'),
    ('Как перестать получать уведомления?', 'Удалите проект из списка ожидания в боте. Чтобы остановить все сообщения, заблокируйте бота в Telegram.'),
]


def help_page(config):
    questions = ''.join(f'<details class="faq-item"><summary>{esc(q)}</summary><p>{esc(a)}</p></details>' for q, a in FAQ)
    content = f'''<div class="page-shell service-page"><section class="page-intro"><span class="eyebrow muted">ВСЁ ПРОСТО</span><h1>Поможем начать<span class="lime">.</span></h1><p>Выбирайте кино здесь. Сохраняйте в Telegram. Получайте напоминания, когда придёт время смотреть.</p></section><div class="service-grid getting-started"><section class="service-card"><span class="step-number">01</span><h2>Найдите проект.</h2><p>Введите название фильма или сериала в поиске либо выберите его в каталоге.</p><a class="text-link" href="/catalog">Открыть каталог ↗</a></section><section class="service-card"><span class="step-number">02</span><h2>Нажмите «+ Ждать».</h2><p>Откройте карточку в Telegram и подтвердите добавление в свой список.</p><a class="text-link" href="{esc(config['bot_url'])}" target="_blank" rel="noopener">Открыть бота ↗</a></section><section class="service-card"><span class="step-number">03</span><h2>Ждите спокойно.</h2><p>Бот следит за изменениями. Список всегда под рукой — можно поделиться им с другом.</p></section></div><section class="faq-section"><h2>Частые вопросы.</h2>{questions}</section><section class="service-support"><div><h2>Подсказки всегда рядом.</h2><p>Откройте справку в боте — там собраны все команды и возможности.</p></div><a class="button" href="{esc(help_url(config))}" target="_blank" rel="noopener">Помощь в Telegram ↗</a></section></div>'''
    schema = {'@context': 'https://schema.org', '@type': 'FAQPage', 'mainEntity': [
        {'@type': 'Question', 'name': q, 'acceptedAnswer': {'@type': 'Answer', 'text': a}} for q, a in FAQ]}
    return layout(config, 'Помощь и ответы на вопросы', 'Как добавить фильм в список, получать напоминания, задать свою дату и поделиться списком ожидания.', content, '/help', schema=schema)


def privacy(config):
    analytics = '<h2>Посещения сайта</h2><p>Мы используем Яндекс Метрику, чтобы понимать, какие страницы удобны и где возникают сложности. Она может использовать cookies и собирать сведения о посещениях, устройстве и действиях на сайте. Управлять cookies можно в настройках браузера.</p>' if config.get('yandex_metrika_id') else ''
    content = f'''<div class="page-shell service-page"><section class="page-intro"><span class="eyebrow muted">ВАШ СПИСОК — ВАШЕ ДЕЛО</span><h1>Конфиденциальность<span class="lime">.</span></h1><p>Какие сведения нужны КиноЖдуну и как управлять своим списком.</p></section><div class="service-prose"><h2>На сайте</h2><p>Для просмотра каталога, календаря и новостей не нужно создавать аккаунт или указывать телефон. При открытии страниц сайт получает сведения о запросе и устройстве, необходимые для их доставки и работы поиска.</p><h2>В Telegram-боте</h2><p>Бот сохраняет ваш идентификатор Telegram, доступные ему имя и username, выбранные фильмы и сериалы, свои даты и историю отправленных напоминаний. Эти сведения нужны, чтобы привязать список к вам, присылать сообщения и избегать повторных уведомлений.</p><h2>Общий список</h2><p>Список не публикуется автоматически. Когда вы создаёте ссылку для друга, получатель видит выбранные проекты и название списка. Считайте такую ссылку доступной каждому, кому вы её отправили.</p><h2>Как управлять данными</h2><p>Удаляйте отдельные проекты из списка в боте. Если хотите полностью удалить сохранённые данные, откройте настройки данных в Telegram и подтвердите удаление. Это удалит ваш список и созданные ссылки на него.</p><p><a class="button outline" href="{esc(config['bot_url'])}?start=privacy" target="_blank" rel="noopener">Мои данные в Telegram ↗</a></p>{analytics}<h2>Внешние сервисы</h2><p>При переходе в Telegram и открытии трейлера на YouTube действуют правила соответствующего сервиса. Эти платформы получают сведения о вашем взаимодействии с ними.</p><p>Подсказки по использованию КиноЖдуна доступны <a href="{esc(help_url(config))}" target="_blank" rel="noopener">в нашем боте</a>.</p></div></div>'''
    return layout(config, 'Конфиденциальность', 'Какие сведения использует КиноЖдун, как устроен общий список и как удалить сохранённые данные.', content, '/privacy')
